UPDATE serial
SET status = 'out',
    outbound_time = CURRENT_TIMESTAMP
WHERE item_id = #{itemId}
  AND serial_no = #{serialNo}
  AND status = 'in_stock'
  AND warehouse_id = #{warehouseId}

UPDATE serial
SET warehouse_id = #{toWarehouseId}
WHERE item_id = #{itemId}
  AND serial_no = #{serialNo}
  AND status = 'in_stock'
  AND warehouse_id = #{fromWarehouseId}
